import time

schedules = [
    {'id': 'report', 'cron': '0 9 * * MON', 'tz': 'America/New_York', 'next': 1000},
    {'id': 'cleanup', 'every': 3600, 'next': 2000},
]

def tick(now):
    due = [s for s in schedules if s['next'] <= now]
    for s in due:
        print('enqueueing scheduled job:', s['id'])
        s['next'] = now + (s.get('every', 7*24*3600))
    return len(due)

print('due:', tick(1500))
print('durable (DB, not memory); idempotent jobs absorb duplicate ticks')

import random, time
random.seed(1)

def run_job():
    if random.random() < 0.7:
        raise IOError('transient: timeout')
    return 'success'

for attempt in range(4):
    try:
        print(run_job(), '(attempt %d)' % (attempt + 1))
        break
    except IOError as e:
        wait = 2 ** attempt + random.random()  # backoff + jitter
        print('attempt %d failed: %s -> retry in %.1fs' % (attempt + 1, e, wait))
else:
    print('-> dead-letter queue (alert on DLQ growth)')
print('retryable (timeout) yes; fatal (bad input) no: classify per error')

# cooperative cancellation: the handler checks the flag
cancelled = {'exp1': False}

def long_job(job_id):
    for part in range(10):
        if cancelled[job_id]:
            print('job %s: checkpointed, partials cleaned, status=cancelled' % job_id)
            return
        # ... do part ...
        if part == 3:
            cancelled[job_id] = True  # user hits cancel
    print('job done')

long_job('exp1')
print('queued: just dequeue; running: signal; finishing: let it land')

prefs = {'export': ['in-app', 'email'], 'thumbnail': ['in-app']}

def notify(job_type, event, detail):
    for channel in prefs.get(job_type, ['in-app']):
        print('-> [%s] %s: %s (%s)' % (channel, job_type, event, detail))

notify('export', 'completed', 'report.pdf ready (signed URL, 1h)')
notify('export', 'failed', 'source timeout; retrying in 60s')
print('preferences per job type: not every thumbnail needs an email')

limits = {'thumbnail': {'cpu': 1, 'mem_mb': 512, 'concurrency': 20},
          'video': {'cpu': 4, 'mem_mb': 8192, 'concurrency': 2}}
running = {'thumbnail': 20}

def submit(job_type):
    if running.get(job_type, 0) >= limits[job_type]['concurrency']:
        return '429: at concurrency cap (backpressure, not OOM)'
    running[job_type] = running.get(job_type, 0) + 1
    return 'accepted (cpu=%d mem=%dMB)' % (limits[job_type]['cpu'], limits[job_type]['mem_mb'])

print(submit('thumbnail'))
print(submit('video'))
print('per-type caps; clear messages; a runaway job never takes the node')

