# scale on AGE (latency signal), not just depth
def desired_workers(age_s, depth):
    if age_s > 120:
        return 10  # starving: scale hard
    if age_s > 30:
        return 4
    if depth == 0:
        return 0  # scale-to-zero for batch
    return 2

for age, depth in ((200, 50), (45, 500), (0, 0)):
    print('age=%3ds depth=%3d -> %d workers' % (age, depth, desired_workers(age, depth)))
print('age > depth: 500 tiny jobs are fine; 1 job waiting 200s is not')
